rows["37:981384963"]="세 눈의 썰매를 봤어"
rows["37:981887951"]="코르티크는 전투에서 동등한 존재가 없습니다!"
rows["37:989073243"]="괜찮아요, 저한테 좋아할 것 같아요"
rows["37:990952745"]="누가 우편 상자를 약탈했나?"
rows["37:994493381"]="이건 도저히 상상도 할 수 없는 일이야!"
rows["37:995511981"]="괜찮은 녀석이란 확신이 필요했거든..."
rows["37:996874642"]="콜라다라는 이제 필사자가 살 수 있는 곳이 아닙니다."
rows["37:999298454"]="나중에 트릭이나 트리핑을 해야지"
rows["380:1619217367"]="아, 젊은 전사야! 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아. 아, 아.$B$B신랑랑 같이 도와줄게 좋겠네 무슨 조언이 있어?"
rows["380:344006757"]="이 어려운 시대 에, 단순한 옷 을 기부 하는 것 은 우리 보다 덜 유리한 사람 들 을 도울 수 있는 큰 도움 이 될 수 있습니다. 옷 은 전쟁 에 있어서 매우 중요 한 옷 과 붕대 를 만드는 데도 큰 도움 이 될 수 있습니다.$B$B만약 당신이 오크에게 옷 조각을 기증하고 싶다면 오그리마저는 기꺼이 받아들일 것입니다. 그리고 그렇게 하는 것에 대한 적절한 공로를 인정받도록 하겠습니다.$B$B호드의 경우!"
rows["381:153046723"]="난 당신을 해치지 않겠습니다. 난 기둥을 탐구하고 그들의 활동을 기록하고 있습니다. 내 사람들은 이상한 것을 알아냈습니다. 방출 또는 어둠이 이 지역에서 오는. 나는 조사하러 왔고, 내가 발견한 것은 매우 불안합니다.$B$B미스터리라는 힘있는 미생국가 외교관이 있는 것 같네요. 그는 포세이큰 중 한 명이라고는 생각하지 않습니다."
rows["381:1598507850"]="로지는 말을 하면서 눈물을 흘리는 것을 막는다.$b$b내 일기, 사라졌어$b$b그것은 대부분 내 아빠의 기억으로 가득 차 있고, 그의 완벽한 도시를 건설할 수 있는 완벽한 장소를 찾아가는 끝없는 탐구로 가득 차 있습니다.$b$b어쨌든, 그의 오래된 스케마들 중 하나가 실제로 유용할 수도 있습니다. 이 뚱뚱한 녹색 풀에서 어딘가에 발견하면 알려주세요."
rows["381:1714470693"]="드디어 제가 찾은 가방입니다. 그리고 이제 여러분께 선물로 드리고 있습니다. 정말 마음에 들기를 바랍니다. 왜냐하면 여러분들이 이 멋진 순간을 평생 기억하기를 바랍니다. 그리고 그 순간을 생각하면, 여러분은 내부에서 미소하게 되길 바랍니다. 왜냐하면 저는 그것을 백만 년 후에 결코 잊지 못할 것임을 알고 있고"
rows["381:1909975119"]="저는 팅크마스터 오버스파크입니다. 저는 오늘날 세계에서 현대적인 거칠고 난형적인 공학 원리들의 주 건축가입니다.$B$B또한, 방사능 제거에 대한 좋은 스케마를 알고 있다면, 우리는 지금쯤에 그 중 하나를 구입할 수 있을 것입니다."
rows["381:1920816593"]="피부를 벗는 것은 죽은 생물의 피부를 제거하고 준비하는 것을 허용합니다. 이 피부는 경매장에서 판매되거나 피부 작업 직업에 지원하는 데 사용될 수 있습니다.\010숙련된 스킨너는 해부학의 마스터가 되고, 목표물을 공격할 확률을 높인다.\010동물의 피부를 벗기기 위해 피부 칼이 필요합니다. 이것은 무역이나 피부 작업 업체에서 구입할 수 있습니다."
rows["381:483223234"]="곤메레건의 망명자들은 더 심각한 곤경에 처해 있습니다.$B$B더 많은 유물을 가져오세요, 우리가 재고를 보충할 수 있도록 도와주세요. 기증하면, 여러분은 모든 곳에서 거미들의 존경과 신뢰를 얻을 것입니다. 그건 돈으로 살 수 없는 것입니다."
rows["381:660950046"]="네, 그 곳! 만약 아이언포지의 왜구의 존경심을 얻으려 한다면, 당신은 귀중한 자원을 기증함으로써 시작 할 수 있습니다! 아이언포지는 천재 조각이 부족하고, 섬유와 붕대가 나무에서 자라지 않습니다.$B$B여러 가지 옷 의 조각 을 돈 으로 사용 하기 보다는, 그것 을 기부 하십시오. 그렇게 하면 아이언포지의 왜성인 들 의 인정을 받을 것 입니다!"
rows["382:1536879863"]="노르건슨의 키스톤에 대한 단서를 찾았는데, 울두어의 기록물들을 보호하고 있지만 타이탄들은 그것을 두 조각으로 나눈 뒤$B$B그 중 하나인 키스톤의 껍데기는 울두르 남쪽 북부 해안에 있는 발명가의 도서관 안에 보관되어 있습니다."
rows["382:757690245"]="저는 젊은 드루이드로서 당신을 지지하는 힘을 대표합니다. 저는 신체의 힘과 마음의 힘입니다. 당신은 이미 훈련을 통해 이것을 알게 되었으며, 곰의 모습을 취했을 때 그것을 이용합니다.$B$B모든 일에 균형을 유지해줘, 젊은여, 그리고 네 관점을 명확하고 진실하게 지켜라."
rows["383:1249352669"]="왔습니다! 다크문 축제가 왔어요! 그 어느 때보다 더욱 멋진 모습으로! 여러분에게 즐거움을 선사하기 위해 비용 따위는 아끼지 않고 전 세계를 유랑하며 진귀하고 놀라운 물건들을 모아 왔습니다. 오늘은 행운이 가득한 날! 남녀노소 누구나 다크문 축제에서 흥겨운 시간을 보낼 수 있습니다! 다크문 축제 상품권이 있다면 잊지 말고 겔바스 그림게이트를 찾아가세요! 놀라운 상품이 기다리고 있으니까요!"
rows["383:1413573155"]="가구 가구 를  ⁇ 어 놓은 상태 에서, 이제 우리는 반제제를 환경 에 도입 할 수 있게 되었습니다. 이 는 스컬지 에게 자신 의 의약품 을 맛볼 수 있게 해 줄 것 입니다!$B$B약국 디터스 (Dithers) 와 함께 가솔린에 사용해야 할 반응제에 대한 정보를 확인하세요. 스컬지!"
rows["383:44307481"]="이 속임수로 우리를 모욕하는 사람들을 신뢰해야 할까요?$B$B우리는 그들이 우리를 구출하려는 것을 알고 있지만, 내 사람들은 그들의 구제를 원하지 않습니다. 우리는 우리 스스로 서있을 수 있습니다. 그리고 우리는 자랑스럽고 분리된 민족으로서 우리의 운명을 추구할 것입니다."
rows["383:540230317"]="울담의 판은 창조자들에 의해 합성된 디스크로 울담 화합물에 접근할 수 있게 해줍니다. 이 디스크들은 여기에 창조자들의 활동에 관련된 특정 데이터를 보관하고 있습니다.$B$B물리적으로, 그들은 현재 소유한 디스크 집합과 둘레로 거의 동일합니다. 그러나 그들의 표시는 울담 복합과 달리 울담에 대한 정보와 직접적으로 관련이 있습니다."
rows["384:1014260080"]="아흐... 그래서, 저는 확실히 여러분들의 시간을 내어 숨을 쉬고 그 끔찍한 괴물과 오랜 싸운 전투 끝에 영웅적인 것에 대해 축하하는 것을 비난하지 않습니다. 당신이 끝낼 때 당신은 나를 잊지 않는 한요. 왜냐하면 제가 작은 사람이지만"
rows["384:1999244081"]="이건 섬세한 일이야, 빨리 할 수 없어, 아니면 뭔가 깨질 가능성이 높지$B$B마치  ⁇ 체 머리처럼!$B$B제 로봇을 생각해봐요, 저는 항상 Mk.I를 만들고 있습니다. 그리고 Mk.II는 뇌가 열광을 당하기 전에$B$B저는 III와 IV를 건너뛰기로 결정했고, 바로 Mk. V로 갔습니다."
rows["384:31893239"]="해 -  ⁇ ! 음식? 우리는  ⁇ 을 먹지 않습니다, 친구, 우리가 악화되지 않는 한. 우리는 돌과 돌과 흙을 먹습니다. 비록 때때로 뼈의  ⁇ 은 맛있는 향수를 만듭니다.$B$B<고르무난은 돌을 들어 올려놓고, 한 거대한 손으로, 당신이 그에게 준 시체를 돌에  ⁇ 고, 마치 케이크에 아이스크를 넣는 것처럼, 그는 반가운 소리를 지르며, 그의 맛을  ⁇ 고 있습니다.>"
rows["384:364583244"]="여기 자라났어, 우린 그들을 해로부터 보호해줬고, 우리가 할 수 있는 모든 것을 해줬고, 많은 사람들이 죽었지만, 많은 사람들이 더 강해졌어요.$B$B<조모 게야가 숨쉬고 있다.>$B$B그는 마음을 잃었고, 내가 그의 균형이 됐다고 말했어요. 나 없이는 그의 아버지를 먹여서 결국 우리 민족을 저주한 피욕이 그를 지배할 것이라고."
rows["384:466228017"]="가끔은 채소가 너무 아름답게 자라는데, 약탈을 요청하기도 합니다.$B$B할아버지는 날카로운 평야새가 시장을 찾는 사람보다 더 좋은 공을 발견할 수 있다고 말했고,$B$B\"열에 있는  ⁇ 보다 더 빨리\".$B$B그 때 그런 말을 할 수 있었겠죠?$B$B중요한 건, 당신은 단지 유능한 작물을 동물으로부터 방어해야 한다는 것입니다!"
rows["384:626124203"]="자이드 숲, 네 바람의 계곡,  ⁇ 라이의 낮은 땅?$b$b그들이 평화를 누리고 있는가? 그들은 여전히 그 평화를 위해 드는 비용을 알지 못합니까?$b$b저는 그들이 하지 않는 것이 더 낫다고 생각합니다. 무지한 사람들이 평화로움을 즐기고, 그들은 걱정 없이 그들의 삶을 맛볼 수 있습니다."
rows["384:723357044"]="아쉽게도 항상 그렇듯 보입니다. 전, 그리고 다른 센리온 서클들처럼, 밀리의 창조물이 고대 전쟁 때 파괴되었다고 가정했었습니다.$B$B비옥의 열매는 살아남았지만 지금은 펠빈이라고 알려져 있습니다. 엘드레'타라스의 그 부문의 악마의 주인인 야생모양인 알진이 부패하고 있습니다."
rows["384:780038382"]="- 알 수 없죠$B$B살아남은 암흑 철인들은 산으로 올라와 도시를 재건하기 시작했습니다.$B$B태우리산의  ⁇ 에서 블랙록 스파이어와 새로운 암흑 철국가들이 일어났다.$B$B어두운 철의 왕국을 지배하던 고대 악의 이야기들이 순환하기 시작했습니다. "
rows["384:811222324"]="가구 가구 를  ⁇ 어 놓은 상태 에서, 이제 우리는 반제제를 환경 에 도입 할 수 있게 되었습니다. 이 는 스컬지 에게 자신 의 의약품 을 맛볼 수 있게 해 줄 것 입니다!$B$B알케미스트 아빙턴과 함께 가솔린에 필요한 반응제에 대한 정보를 확인해 보세요. 스컬지!"
rows["384:976451049"]="안녕하세요, 친구. 잠시만...$B$B테일드라시를 설립하는 과정에서 많은 시행착오를 겪었습니다. 만약 그 시대의 끊임없는 갈등이 충분하지 않았다면, 우리는 지금 엄청난 천재 부족에 처해 있습니다. 만약 여러분이 재료를 남겨두고 있다면, 저는 여러분께 자선을 부탁드립니다."
rows["385:1184804973"]="인간들은 불모의 땅의 가장자리에 숙소를 지었습니다. 그들은 그것을 그림자 휴식이라고 불렀습니다. 몇 주 전에, 그것은 불태웠어요.$b$b왜 신경쓰지? 저는 인간에 대해 전혀 몰라요. 하지만 그 호네에 스파이가 있었거든요.$B$B도움이 되고 싶다면 Shady Rest Inn의 유해로 가서 찾아낸 모든 단서를 내게 돌려주십시오."
rows["385:644396886"]="마법사 우롬은 세 번째 반지를 보호합니다. 그는 혼자와 무력으로 보일 것입니다. 그러나 외모로 속이지 마십시오! 우롬은 강력한 마법사입니다.\010붉은 비행기에서 드레이크를 불러낼 수 있는 힘을 줄 수 있어."
rows["385:739803025"]=" ⁇ 스톤을 줘서 내가 내버려두고 피우스를 켜게$B$B총에 맞은 후 잠시 떠다니는 거지만 내가 줄 날개를 떨어뜨려서 빨리 내려갈 수 있어요$B$B당신은 해안에서 바로 물 속에 떠 있는 큰 목표물을 겨냥하고 있습니다.$B$B아직 바닥에 있는 동안 날개를 떨어뜨리지 마... 난 생명보험을 팔지 않아요!"
rows["385:791177471"]="감사합니다 빛 지금 이 순간 두머리 괴물한테서 도움을 받아 들일 수 있어요\010도시 는 트로그스 로 덮여 있습니다! 그들을 멸종하려는 시도 는 대량 오염 을 초래 했습니다. 하지만 여전히 희망 이 있습니다.\010아이언포지로 이송된 우리 과학자들은 이 병의 치료법을 연구하고 있습니다. 한편, 트로그 침략을 막는 데 도움이 된다면, "
rows["385:980811810"]="아라토르, 내가 안 돼 15 우린 오래전부터 그를 죽었다고 생각했었지 하지만 알아두세요, 내가 할 수 있는 모든 것을 해봤어요. 그를 찾으려고 노력했어요. 지옥불의 경계에서 나가란드 황폐까지, 우리는... 아무것도 없이 찾아봤습니다."
rows["386:1147387311"]="내가 어떻게 생각하는지 아시나요? <토마는 그의 뒤를 빠르게 쳐다보며>$b$b사우르 사제들은 마을만큼 더러운 것들이 가득합니다.$b$b그들의 크로시크 숭배가 그들을 약하게 해줍니다. 그들은 힘을 전파하지만 사냥을합니까? 그들은 죽이고 있습니까? 그들은 타락한 형제의 부패한 유골에 굴러가요?$b$b아니, 그들은 동굴에 숨어서 얘기하고, 만약 그들이 정말로 강한 사람이라면,"
rows["386:1248893763"]="가흐즈란카를 잡으려면 특별한 무드스칸크 매력이 필요해요$B$B하지만 매개뿐만 아니라,  ⁇ 스커스도 필요해요. 매개 안에 넣어서 낡은 냄새가 나게 해줘야죠!$B$B진흙  ⁇ 이 있을 때,  ⁇ 레의 지점에서  ⁇ 을 던져주십시오. 그리고 술 한 잔을 마시고 기다립니다. 하지만 너무 오래 기다리지 마세요. 가흐즈란카는 확실히  ⁇ 을 줄 것입니다!"
rows["386:1482820528"]="이 곳에는 말할 수 없는 공포가 살고 있습니다. 아제로스 우리가 알고 있는 것처럼$B$B메리트라는 천년 전에 카엘레스트라스와 아리고스와 함께 자신을 희생시켰습니다. 왜냐하면 그들은 또한 이것을 알고 있었기 때문입니다. 우리는 그들을 위해 돌아온 맹세 때문에 여기 있습니다."
rows["386:1542871806"]="일리던은 그의 수년간의 봉사에 대한 보상이 되면서 칼타스에게 5명의 전사를 보내서 훈련하도록 허락했다.$B$B훈련은 잔인했고, 이리리던은 카엘의 전사들을 가장 뛰어난 악마 사냥꾼들을 물리칠 수 있는 시험에 놓았다.$B$B카엘의 엘프들 중 세 명은 훈련 중에 죽었고, 또 한 명은 미쳤어요.$B$B한 명은 성공했습니다."
rows["386:1665131801"]="- 느낄 수 있어?$B$B죽은 자들의 날 에 영세계 가 가까이 다가오고 있습니다. 그래서 우리는 꽃과 촛불과 제물로 사랑하는 죽은 자들의 무덤을 장식합니다.$B$B그러므로 와서 나와 함께 춤추라 우리가 그들의 유령의 존재에서 잃어버린 사람들을 소중히 여기고 존중해 주자"
rows["386:1699252723"]="나 야간 엘프입니다. 당신은 제 종류에 대해 아무것도 모르지만, 우리는 당신과 당신의 조상들에 대해 많이 알고 있습니다.$B$B당신은 내 동맹군들을 도와주었고, 그 때문에 감사하고 있습니다. 하지만, 현재는 당신은 희미한 길을 걷고 있습니다. 어쩌면 시간이 지나면, 당신은 내 마음 속에 있는 의심과 두려움을 해소할 수 있을 것입니다."
rows["386:1710143353"]="크로스는 우리의 창조자이며, 약한 자들을 구원하지 않을 것입니다.$b$b만약 당신이 강하다면 크로스는 사냥을 할 수 있게 해 주며 당신의 영원은 약자를 쫓아다니며 그들의 육식을 먹고 점점 더 강해지도록 할 것입니다.$b$b힘겨워요, 사우로크$b$b항상 스 ⁇ 블레이드에게 힘!"
rows["386:1971383651"]="그 동상이 고통스러울 것 같았어요. 그 동상이 물에서 올라와 크레인과 잘 타이밍된 폭발물 같은 것 같았어요. 하지만 위크는 우리가 더 안전하고 덜 피해를 줄 수 있다고 생각했습니다.$B$B이제 봐요, 우리는 모든 것을 잘못  ⁇ 어 놓았어요. 그리고 우리가 정상에 도달하면, 그러면?$B$B우린 여기서 오래 있을 거라는 생각이 들어요"
rows["386:539569340"]="저는 샤도-판을 따라 벽 너머에 그들의 많은 행적을 기록합니다. 그것은 쉽지 않습니다 - 저는 전투의 혼란 속에서 제 일간지를 잃지 않으려 합니다!$b$b이 일은 이미 일어났어요. 로레워커들은 오랜 세월 동안 판다르네 역사를 기록해 왔습니다. 그들의 메모는 파다리아 전역에 흩어져 있습니다."
rows["386:846411980"]="백 보안 카드 삽입 성공...$B$B보안 레벨 베타 단위를 배급합니다.\01001010000 01101100 01100001 01111001 00100000 01110100 01101000 01100101 00100000 01010111 01100001 01110010 01100011 01100001 01110010 01100110 01110100 00100000 01110010 01101111 01101100 01100101 01110000 01101100 01100001 01111001 01101001 01101110 01100111 00100000 01100111 01100001 01101101 01100101"
rows["386:867764709"]="서, 아니, 서! 또 다른 파견이 트랜킬린에서 도착했습니다. 다시 최고 집행자 마브렌입니다. 캡틴. 이번에는 편지 언어는 매우 '색'이었습니다. 그는 그의 요청을 반복합니다. 우리가 데토올메에 대한 노력을 지원하는 파스트라이더를 모셔라"
rows["387:877042007"]="오, 예, 발은; 그것은 놀라운 물질입니다. 적절한 촉매와 함께 그것은 적용 된 모든 것을 거의 불멸의로 만듭니다. 나는 그것을 재프로그램 된 발-오-트론 800와 함께 채취하고 있습니다. 그리고 나는 확신이있다 내가 혼합물을 올바른 이번에는. 나는 단지 몇 자원 봉사자 필요 합니다. 적절한 생물에 대한 테스트를. 당신은 어떻게, 친구?\010*불멸성, 특정 제한 사항이 적용됩니다."
rows["388:113167387"]="미니어 탱크, 또는 우리가 똑똑하게 이름 붙인 토닉, 내가 기억할 수 있는 한, 페어 좋아하는.$b$b우리는 2개의 경기장을 토크 전투에 전용하고 있습니다.$b$b한 경기장은 시계를 향해 달려가서 목표를 파괴하고 적의 기구를 피하는 것입니다.$b$b다른 아레나는 자신의 탱크나 미니제프를 이용해 친구들을 싸울 수 있는 곳입니다."
rows["388:1140919917"]="이 기기를 만들면, 그냥 그 기기를 활성화시켜서 아름다운 가젯잔으로 옮겨갑니다.\010다른 우주에서 온 악인들로 대체되는 트랜스포테이즈에 문제가 있다고 보고됐지만, 곧 해결될 거라는 확신이 있어요."
rows["388:1205407739"]="옛 왕국의 어두운 시절부터 우리는 판다레인이 우리의 정신과 힘을 높이기 위해 신비로운 맥주 제조 기술을 사용했습니다.$B$B지금 우리가 말하는 동안, 맥주 제작자들은 세계에서 떠돌고 다니며$B$B이 불가피 한 맥주 주인을 찾아서 도움 을 베풀는 사람 들 은 맛있는 아이템 을 얻을 수 있습니다. 적어도, 당신은 많은 맥주 를 마실 것 입니다!"
rows["388:969374338"]="아비아나가 잃어버린 수호자 천국의 새 신자여, 10천년 전 악마 군중들과 싸우다가 죽었습니다.$B$B타론의 드루이드는 성당 안에 있고, 우리는 그들의 지원이 필요할 것입니다. 당신은 그들을 도와야 합니다. 그리고 Aviana를 도와야 합니다."
rows["389:1069581195"]="스톰 피크스 내에 있는 77-79 레벨의 던전인 돌의 홀은 이제 테스트를 할 수 있습니다. 던전으로 이동하기 전에 전체 그룹에 가입하시기 바랍니다. 멘팅 톤은 아직 이 던전에서 사용할 수 없습니다.\010돌의 홀을 떠나려면 그냥 정규 출구로 출입해 감옥 안으로 들어가면 다시 이 곳으로 돌아오게 될거야"
rows["389:1134976489"]="난 아웃랜드 아라티 계곡의 해독자들을 상대로 도와주는 강력한 유물을 발견하기를 희망했지만 이 마법 같은 허리옷을 발견했고, 미소한 괴물 사이드  ⁇ 이 있었고,\010$b\010어쨌든, 내가 계속 검색하는 동안 리그와 함께 싸우려 하겠나?"
rows["389:1230457643"]="난 죄수이야!$B$B날과 제 아름다운 젤펠린을 하늘에서 떨어뜨렸어 호드이건 새로운 건 아니잖아$B$B해적들을 폭격하기 위해 날 해프로 주위를 돌게 하고 난 그녀를 이렇게 유지할 수 있는 부품을 갖고 있지$B$B내가 말해주는 범죄야!"
