rows["390:1261392103"]="내 백성의 풍요를 맛보라 한 번이라도 살기 좋은 것들을 맛보라 그때는 네가 하나님 손에 닿았다는 것을 알고 순전히 죽을 수 있을 것이라$B$B피의 엘프 - 남자, 여자, 아이 같은 거부하는 사람으로부터 당신의 방향으로 날아갈 수 있는 스피틀에서 마시십시오.$B$B실버문 당신과 함께, 야만전사!\010"
rows["390:1293257981"]="제3차 전쟁 이후 그런 군대가 늘지 않았죠! 바리안은 스컬지 위협을 직접적으로 해결하려고 준비되어 있습니다.$B$B노스렌드로 가고 있습니까? 저는 그 곳까지 가본 적이 없지만, 이 땅은 아름답고 배신적인 나라이기도 하다."
rows["390:1956177940"]="광업 은 야생 과 지하 에 있는 광업 노드 에서 광물, 광물 및 돌 을 찾아내고 광업 할 수 있다. 이 광물 은 경매 집 에서 판매되거나 수자, 공학 또는 보석 전문 을 지원 하기 위해 사용될 수 있다.\010또한 숙련된 광산업자들은 힘겹게 성장하고 수익이 증가한다 체력.\010광산을 위해 광산 선택이 필요합니다. 이것은 무역 또는 광산 공급업체에서 구입할 수 있습니다."
rows["390:757657808"]="제 형제 들 의 대부분 은 호드 의 \"바르바르적\" 인 방법 을 경멸 합니다. 그리고 한 때 저는 그 들 가운데 나 를 포함 해 보았습니다.$b$b하지만, 학창 때 에 우리 의 주변 에 있는 것 들 을 중요 히 인식 하게 되었는데, 그 들 의 매력 은 어느 정도 가 있다고 생각 하지 않나요?$b$b...당신은 물론 제 공부에 관심이 없을 겁니다."
rows["391:1408825621"]="센라리온 회원의 요원들은 엘드레타라스의 현재 상황과 관련된 불안한 정보를 발견했습니다. 저는 이 문제에 대해 어떻게 해야 할지 막상 상태에서 있고, 곧 전투에서 스스로 대처할 수 있는 능력 있는 몸집이 있는 존재들의 도움을 요청할 것임에 틀림없습니다.$B$B하지만 엘드레'타라스에서 제대로 행동하는 것은 '생산의 열매'라는 명맥을 이해하는 것입니다."
rows["391:1718464915"]="그 다음, \"로카르 오가르! 승리와 죽음 - 이 말 들 이 나 를 호드 에 묶어 놓습니다. 왜냐하면 그것 들 은 호드 의 모든 전사 에게 가장 거룩 하고 가장 근본적인 진리 들 이니까요.\010난 내 피와 육체를 전쟁의 장군에게 자유롭게 바치고 난 나의 전쟁의 장군의 욕망의 도구이고 난 나의 전쟁의 장군의 지휘의 무기입니다\010이 순간부터 마지막 날까지 나는 살아 죽는다 - 호드를 위해!\""
rows["391:327476902"]="가로시 지옥의 제자가 된 것처럼 말했어요. 우리 \"고수\"는 자랑스러워요.$b$b하지만 호드 MIN은 무장 없는 아이들을 싸우지 않는다. 또한 나는 우리 전쟁을 이 신성한 방으로 데려오려고 용기를 하지 않을 것이다.$b$b게다가 이 작은 놈은 대장인 베이인 블러드후프의 친목과 신뢰를 얻었으니$b$b- 아직은"
rows["392:520129030"]="켈레다나스 섬 외곽에 해산한 태양 공격은 큰 발전을 이루었습니다. 킬제덴의 세력은 뒤로 밀려지고 있으며 혼란 속에서 저는 이 곳 선웰 고원도에 작은 스카우팅 세력을 이끌 수 있었습니다. 제 군대는 파헤일온 플라자를 거쳐, 선블레이드 피 엘프들을 발견했고, 적을 맞닥뜨렸습니다. 그 전투는 빠르게 재앙으로 변했습니다."
rows["393:1501890334"]="난 모든 걸 찾고 있어, 하지만 그 표지판은 네가 말하는 케그 보호자 표지판이야$b$b다크 아이언  ⁇ 을 격파할 때마다, 표적을 얻습니다.$b$b이 티켓을 내놓는 것이 아픔이지만 다시 만나고 또 떠날 수 있다는 의미도 있어요"
rows["393:1748671623"]="저는 젊은 드루이드로서 당신을 지지하는 힘을 대표합니다. 당신은 이 힘을 배우기 위해 내게 왔어요.$B$B내 정신을 의지하는 것이 무엇을 의미하는지 알기 위해서는 몸의 힘과 마음의 힘의 중요성을 이해해야 합니다."
rows["393:414690574"]="너무 어린 사람에게 강력한 반응기, 당신은 당신의 이름으로 많은 적들을 죽일 것입니다. 얼라이언스하지만 위대한 순환에서 탄생은 죽음만큼이나 강력하다는 것을 기억하는 것이 중요합니다.$B$B오누는 천천히 머리까지 올라가서 눈에 띄지 않는 아코른을 꺼내서 무두르기로 팔을 내려놓는다.$B$B이것은 매우 강력합니다.$B$B... 사과합니다. 오만처럼 들리지 않았으면 좋겠습니다."
rows["393:638343028"]="동쪽쪽의 Netherwing Fields에 드래곤마우 요새가 있다. 그 곳에서는 잔인한 드래곤마우 오크 클랜이 그들이 포획한 드래크들을 고문하고 그들의 의지로 굴복시키려 한다. 많은 사람들이 희망을 포기하고 그 대신 드래곤마우의 명령을 선택한다. 다른 사람들은... 드래곤마우 전쟁 당국이 그들을 포획하고 요새로 데려가지 않을까 두려워 착륙을 거부한다."
rows["394:1229142988"]="스톰 피크스 내에 있는 80 레벨의 던전인 라이트닝 홀은 이제 테스트를 할 수 있습니다. 던전에 이동하기 전에 전체 그룹에 가입하시기 바랍니다.\010번개의 방에서 나가려면 그냥 정규 출구로 빠져나와 감옥 안으로 들어가면 다시 돌아오게 될거야"
rows["394:1386470983"]="아나크로노스가 비행에 맡긴 벼슬 조각을 자기 만든 미노 위에 올려놓고 이제 내가 미노를 숨기도록 강요하는 아칸이트 부이나 뭐라 생각하니?\010"
rows["394:1625278620"]="카자미트... 전설이 가지고 있는 물건은 모든 괴물 종족이 알케미와 공학의 최고 마스터로 진화하도록 도와줬어?$B$B그것은 우리가 우림 트롤 강제들을 무너뜨리고 케잔을 통제하는데 도움을 준 물질입니다. 평화롭게 쉬게 하소서. 그리고 그것은 모든 존재의 가장 귀중한 무기입니다.$B$B그 원숭이에 어떤 영향을 미치지는 않나요?"
rows["394:1801729268"]="신입원 서류를 서명하지 않겠지만 그와 함께 싸울 거야$B$B아더가 스트라톨메를 죽이고 말'가니스를 물리칠 수 있도록 해야 해$B$B아타스와 얘기하면 말'가니스의 세력을 파괴하는 일을 하게 될 거야"
rows["394:1991654376"]="필사자 여러분, 이 곳을 포위하는 끔찍한 부패로부터 저를 해방시켜주셔서 감사합니다. 아직 완전히 회복되지 않았지만,\010내가 당신과 당신의 친구들에게 발명속도를 부여해... 당신의 손상을 증가시키고 움직임을 증가시킬 수 있고..."
rows["394:2005711087"]="트롤 마법의 고령 버전이 얼마나 약하고 아픔스러운지 아세요?$B$B고령들은 왜 그들의 마법적 친밀감으로 이루어진 사람들이 트롤 우두의 힘과 싸우고 있지 못하는지 이해할 수 없었습니다. 이것은  ⁇ 한 피부가 이해할 수 있는 상상할 수 없는 개념이었습니다. 그들은 트롤 매력을 악당화 된 버전으로 사용하는 것을 포기했습니다. 그들은 그들을 '아르칸움'이라고 불렀습니다.\010"
rows["394:851891164"]="[이 질문을 한 후 눈에 띄는 휴식거리가 있습니다.]$B$B여러분이 요청한 정보는 현재 이 저장소의 데이터 사이클에 없습니다. 이 방치에 대해 진심으로 사과합니다.$B$B이 정보 저장소에 데이터 사이클 업데이트가 수행된 후 이 정보를 요청하시기 바랍니다. 또한 아제로스에 위치한 다른 정보 저장소에서 이 정보를 요청할 수 있습니다."
rows["395:1383811195"]="윈저는 그날 특히 화를 내렸어요. 그리고 믿으세요, 윈저에게는 엄청난 성취였습니다. 그는 제게 계속 '어떤 일이 잘못됐다고' 말했어요.$B$B우리가 블랙록 산 한가운데에 있었는데, 더러운 동물들이 공격했습니다. 오크들을 말하는게 당연합니다. 주의를 기울여 주시겠습니까? "
rows["395:894126816"]="<하워톤은 눈 ⁇ 을  ⁇ 니다>$B$B'사격'이라는 용어를 사용하지 않기를 더 좋아하지만, 예, 공격은 무결히 진행되었다. 우리는 타우라조를 방정식에서 제거하고, 그 의 의 무기를 압수하고, 그 의 금기 시설을 파괴했습니다. 공격은 우리 의 군대에 상당한 호흡 공간을 제공했고, 적 의 균형을 잃게 했습니다.$B$B하지만, 공격 중에, 저는 제 부하들에게 우리의 선에 구멍을 놔두고..."
rows["396:1313791147"]="병의 물결이 날 덮어 버렸습니다. 의식이 끝난 후, 저는 집으로 달려갔어요. 아이들을 찾아 갔습니다. 제가 품에 걸을 수 있는 모든 물건을 모아서, 소년들과 함께 떠났습니다. 우리는 언덕으로 달려가서 숨어들었습니다.$B$B하루도 지나지 않아 내가 이 부분을 생각하지 않는다 20 그 원소들과 재결합하기 위해 몇 년이 걸렸습니다. 20 원소가 치유되기까지 몇 년이 걸렸습니다."
rows["396:1825278508"]="청동색 용 비행. 그들은 나를 죽음의 가장자리에서 빼앗아 그들의 주인 노즈도르무 앞에 데려갔습니다. 그는 나를 감시하고 사냥을 계속하기를 원한다고 말했습니다. 그는 나에게 경관으로서 불멸을 부여했습니다. 그의 에이전트 중 한 명으로서 아제로스의 역사를 증언하도록 위탁되었습니다.$B$B저는 엑스란타우르 증인입니다. 아제로스 잊혀지지 않도록"
rows["396:526783763"]="스리 라 마을의 어머들은 그들의 마을에서 비정상적으로 많은 암초 옥토피를 보고하고 있습니다. $b $b 문제는 여우기들이 몰려오는 증가가 껍데기 개체에 큰 피해를 끼치고 있다는 겁니다. 그리고 모든 사람들이 진짜 돈이 껍데기 안에 있다는 것을 알고 있습니다. $b $b 한두분 동안 그  ⁇ 을 안겨주면, 아마 이 여우들의 무리를 가지고 도망칠 거야"
rows["396:979896467"]="해발 보호자 중 하나를 발견하면 엘프가 가까운 해발 보호자를 다시 활성화시키려 하겠는데. 이를 막기 위해 빨리 죽여라."
rows["397:384525274"]="툴덤의 여러 세트 판은 창조자들이 표현한 사용에 대해 합성했다. 창조자들은 이 세상의 모든 복합체에 대한 상기 디스크의 배포를 통제한다. 따라서 아제로스는 방문을 위해 재계획되었으며, 따라서 미래의 디스크는 그 시간에 순환에 들어갈 수 있다.$B$B기존 디스크는 적절한 보안 허가를 받아 해당 당사자에게 완전히 배포되었습니다."
rows["398:1062979734"]="여행 중에 저는 위스플록의 레시피를 배웠어요.$B$B이 옷은 체력, Spellpower, 지능 및 마나 복구를 제공하는 거래 가능한 에픽 매킹 매킹입니다. 이 레시피를 가르쳐 줄 만한 사람을 찾고 있습니다.$B$B노스렌드의 모든 정상적인 던전들을 완성하고 노스렌드 던전 마스터의 성과를 거둔 사람은 위스플록의 레시피를 배울 가치가 있을 것이다."
rows["398:1319279820"]="그는 무조한 룬을 가져갔고, 그  ⁇ 은  ⁇ 은  ⁇ 을 만들 때 사용했고, 돈을 지불하지 않고 도망쳤어요.$B$B내가 궁금한 건 그가 블랙록 스파이어에서 안전하게 앉아서 원료로 물건을 만들려고 노력할 수 있을까?\010"
rows["398:455051508"]="아무도 못 보고 있어서 내가 얼마나 무시당하는지 아세요?$B$B그럼, 내 전직 용병사에서 살아 있는 어떤 사람이 보내셨겠죠?$B$B하지만 비활한 이야기 그만해, 당신이랑 내가 할 일은 많아요. 만약 당신이 일을 바로잡고 발탈라크의 정신을 그에게 돌려주려고 한다면!"
rows["399:1074997921"]="내 얼굴에서 벗어나, 내 훈련이 안 보여? 네, 네 진짜가 차기 워마울 챔피언이 될거야.$B$B네, 난 북쪽의 웃는 두개골 유적에 있는 피의 반지를 거의 준비하고 있어. 하지만 생각도 하지 마, 꼬마. 넌 너무 약해. 반지의 알리는 거트하크는 반지를 들여다볼 수 없는데,$B$B이제 너보다 먼저 이길 거야"
rows["399:1541759550"]="드디어 이 감옥에서 해방됐어요$b$b키린 토르는 나로 달라란에서 보내서 실버파인 숲에서 아루갈이 죽은자와의 진전을 조사해봤는데 마법사가 정신을 잃었는지 몰랐어요$b$b이 엉망이 닥쳤다고 보고해야 하지만 떠나기 전에$b$b레틸고르를 물리쳤고, 어쩌면 너보다 더 멀리 있는 것을 살아남을 수 있을지도 몰라"
rows["399:1553582090"]="상황이 심각하다, $p.\010호드는 Zan'vess의 심장 근처에 있는 매티드 무기의 저장소를 찾고 있습니다.\010호드보다 먼저 섬을 덮고 있는 방패를 통과하고 무기를 확보해줘요"
rows["399:1730379718"]="처음 도착했을 때, 저는 마을의 동명인 사람을 만나기를 희망했습니다.$B$B로즈엘레스는 돌아다녔다.$B$B대부분의 젊은 고래들은 첫 번째 연습생에 도달할 때 '나는 장악자가 되고 싶다'라는 단계를 넘어서서$B$B아무도 꿰매기사가 되겠다는 꿈을 꾸지 못하지만 우리 엄마는 말했듯이 파스트라이더들이 벌거벗은 채 돌아다니는 것은 불가능해요"
rows["399:403192809"]="블랙록 캐버너스 (Blackrock Caverns) 는 블랙록 산에 있는 수준 79-81의 던전이다. 던전에 이동하기 전에 전체 그룹에 가입해 주시기 바랍니다.\010돌의 홀을 떠나려면 그냥 던지온 내부의 정상 출구로 나가면 다라란으로 이동할 겁니다."
rows["399:633468256"]="이것은 \"어린 인내\"의 이야기입니다.$B$B이 곳인 사람들의 왕 바리안 류인은 밤 엘프의 달 여신과 그들의 민족의 지도자인 타이란데 위스퍼윈드에게 인내심을 조언했습니다.$B$B바리안 왕의 계획은 - 그리고 용기 있는 3명의 모험가들의 작업! - 스카르가시 사령관의 호드 세력보다 훨씬 적당한 상황에도 불구하고 레드 크레인 성전에서 얼라이언스 승리를 거두었다."
rows["399:685270477"]="제가 여러분께 드리는 것은 바로 그런 칼입니다. 불타지 않고, 가열되지 않고, 처리가 되지 않은 것 입니다.$B$B이제 당신은 용을 찾아서 칼을 매료시킬 뿐이다.$B$B만약 당신이 영원히 살 수 있다면, 이것은 가능할 수도 있지만, 당신은 필사적이어서 언제든 존재는 멈출 수 있기 때문에, "
rows["39:1006219501"]="내 일으로 돌아가서 난 바쁜 괴물이야"
rows["39:1009389500"]="우리도 나중에 저들 틈에 껴서 춤을 추겠지요."
