rows["39:950512928"]="저는 세 번째 방법을 선택하겠습니다. 죽어라!"
rows["39:951409898"]="어서 열어보게. 맘에 들 것 같은데..."
rows["39:959782094"]="탈출 경로일 수도 있겠죠"
rows["39:969261904"]="더 빨리 파는 거 아냐"
rows["39:977971630"]="고통의 힘을 끌어내, 죽음의 기사!"
rows["39:978108875"]="넌 성공했어, 썬더파우 피난처가 구해졌어!"
rows["39:978539756"]="내 반려동물도 널 태워버릴 거야!"
rows["39:978923947"]="저는 디자이너 섬을 내 고향으로 만들고 싶습니다."
rows["39:979068753"]="적군이 감지되었소. 전송 종료!"
rows["39:980639190"]="바다와 땅이 우리에게 생명을 주었습니다."
rows["39:981058161"]="%s은 미묘한 스크리닝을 시작합니다."
rows["39:981759922"]="지금 이 순간부터 아무것도 남지 않을 것이다!"
rows["39:982379435"]="빨리, 같이 볼 수 없지"
rows["39:982577483"]="넌 적당한 적이야 오늘 네 날이야"
rows["39:984437449"]="이 다지는 칼을 찔러서 잘 쓰인다."
rows["39:987266321"]="무슨 소리야?"
