rows["3:2091068"]="- 그래"
rows["400:1369581582"]="틸러스는 당신을 보석으로 장식하거나 전쟁에 준비하지 않을 겁니다.$B$B농부의 삶은 조금 다른 것 같습니다.$B$B만약 당신이 그것을 지키면, 당신은 정말 흥미로운 사람들을 만날 수 있습니다. 당신은 당신의 자신의 농장을 짓고,$B$B이 모든 것이 흥미롭다면, 하프힐로 가서 직접 보셔야 합니다!"
rows["400:2049229713"]="이 글자는 마법의 서적, 글리프, 무작위 도마, 다크문 카드, 심지어 다른 직업에 대한 요리법을 만들 수 있습니다.\010이 글쓰기의 많은 원료는 허벌리즘이 수집한 허브를 밀러하는 데서 만들어졌습니다. 그래서 두 직업은 잘 어울립니다.\010이 글자를 새기기 위해 가상 잉크 세트가 필요합니다. 이 글자와 다른 필요한 재료, 즉 문장 등은 새기판사에서 구입할 수 있습니다."
rows["400:734904535"]="오래전, 제 삼촌인 자에타르의 고문된 영을 해방시키기 위해, 제 삼촌 자매들과 함께 이 동굴에 들어갔지만, 그 동굴들 사이에서 이미 퍼져 있던 부패는 곧 우리를 정복했고, 우리도 쓰러졌습니다.$B$B우리는 이 경로를 돌아다니게 되어있었고 우리의 마음을 독해주는 독소들이...$B$B비록 지금 내 정신이 안심하고 있지만, 나는 내 임무에 실패했다고 알고 있습니다."
rows["401:1493852146"]="나는 창조주의 불길이 씻어내린 세상을 보았다. 모두 변변히 저항도 못하고 사그라졌지. 너희 필멸자의 심장이 단 한 번 뛸 시간에 전 행성계가 탄생하고 무너졌다. 그러나 그 모든 시간 동안, 나는 공감이란 감정을... 몰랐다. 나는, 아무것도, 느끼지, 못했다. 무수한, 무수한 생명이 꺼졌다. 그들이 모두 너희처럼 강인했더냐? 그들이 모두 너희처럼 삶을 사랑했단 말이냐?"
rows["401:199453848"]="한 부족의 어머니의 의무는 듣기, 바람과 물과 불과 땅을 듣기, 다른 사람들이 가죽을 모으는 방식으로 그녀의 부족에 정보를 수집하는 것입니다. 나는 꿈에서 카슈르 어머니와 소통합니다.$B$B<조모 게아가 웃는다.>"
rows["401:2104136867"]="우리 민족은 이 수용소에서 인간에게 노예로 잡혀있었고, 저는 이 교두방에 갇혀 있었고, 내 형제들이 이 줄기 속에 갇혀 있고, 그 목에 매달려있음을 보았습니다.$B$B우리 모두의 리더 오그림 둠햄러가 뒤에서 칼을 찔러 죽었음을 봤어요. 그의 피가 우리가 서 있는 땅을 검은색으로 지게 했습니다.$B$B이제 우리 모습을 보세요. 이것이 우리의 유산입니다. 우리는 모든 것을 잃었고,"
rows["401:717961797"]="컨소시엄은 몇 달 동안 이 작전을 계획해 왔습니다. 우리는 우주에서 가장 큰 다이아몬드를 발굴해야 했습니다.$B$B시작하기 몇 분 전에, 넥서스 왕자 하라마드는 우리가 네더스톰에서 정치적 문제가 해결될 때까지 대기해야 한다는 메시지를 보내서"
rows["401:841552210"]="창조자들은 이 저장소에 저장된 정보의 규모를 알고 있습니다. 그 후, 여기 저장된 데이터의 휴대용 복사본은$B$B이 지식을 흡수하기 위한 여러분의 가시적인 요구사항을 완전하게 고려해 보세요."
rows["402:1156324970"]="고왕은 가로쉬가 그의 미친 캠페인을 계속할 것을 원치 않습니다. 그것은 너무 많은 무고한 생명을 희생하고 있습니다.$b$b우리는 취약점을 찾아서 오그리마방어방위, 취약점 얼라이언스 군대가 이점을 쓸 수 있습니다.$b$b불행히도 가로쉬가 무작위로 일하지 않았다고 보아도 Kor'kron의 모집을 강화하고 완전한 전쟁 기계로 바꾸어 놓았어요"
rows["402:2000531949"]="저는 그들이 무자비하게 그를 때리던 것을 지켜봤습니다. 그들의 무자비한 중위원도 그러한 잔인함은 정상적인 행위처럼 행동했습니다. 야만적인 때림으로, 저는 나 자신을 깨지는 것을 느낄 수 있었습니다.$B$B비디케이터 사루안이 때리는 것을 보면서 울기 시작했어요. 두려움에서 아니라 슬픔에서 울었습니다.\010"
rows["402:442498169"]="안녕, 여행자, 이 길을 찾는 사람은 많지 않아요.$B$B내 이름은 리버른이고, 난 윈터스프링 프로스트스바버를 마운터로 훈련시켜요.$B$B이 고양이는 가장 야만적이고 가장 어려운 사벌입니다. 가장 신뢰하고 높은 사람이 그 말을 타고 시도할 수 있습니다.$B$B저는 그런 마운트를 그냥 누구에게도 팔지 않을 겁니다. 아니, 당신은 그것을 위해 노력해야 합니다. 그리고 내 편뿐만 아니라 검 자체로 당신의 인정을 얻어야 합니다."
rows["402:732236350"]="보너티 테이블은 5개의 순례자 보너티 음식으로 각 의자에 하나씩 배치되어 있습니다.$B$B의자 에 앉아 있을 때, 그 음식 을 원하는 만큼 먹을 수 있고, 그 음식 을 다른 의자 들 에게 전달 할 수 있습니다.$B$B만약 여러분이 한 음식으로 충분히 섭취한다면, 그 음식에 대한 특유의 혜택을 얻을 수 있습니다.$B$B또한, 모든 음식을 충분히 먹으면 공유의 정신을 얻게 될 것입니다!"
rows["403:108387016"]="순수한 금의 표면에 새겨진 내 유감, 수치, 후회, 슬픔의 실체였다. 불행히도, Twilight's Hammer는 표지를 발견하고 나를 욕설자라고 표시했다. 나는 요약적으로 처형되었다. 엘루네에게 내 기도는 불완전했다. 나는 이제 이 세상에 묶여있다. 영혼으로서, 내로 넘어서지 못하는; 이  ⁇ 구에서 모든 Twilight's Hammer의 믿음을 배신하는 모든 사람들에게 경고로 보관.\010"
rows["403:487284833"]="경쟁의 영을 아세요?$B$B두 년 마다 그들은 필사적 영역에 가까워진다. 그러한 시간 동안, 얼라이언스 과 호드 의 구성원들은 서로 물리치고 그들의 호의를 얻기 위해 경쟁자 타바드를 전투장에 착용합니다.$B$B난 이런 혼란스러운 시대를 기억하는 기념품을 저장해두고 있어"
rows["404:1065614928"]="아제로스 최고의 행사인 다크문 축제에 오신 모든 분들을 환영합니다! 맛난 음식과 독한 술, 이국적인 유물과 깜짝 놀랄만한 물건들, 그리고 점쟁이의 운명 상담 등 눈이 휘둥그레질만한 재미가 끝없이 준비되어 있답니다! 다크문 축제 상품권이 있다면 잊지 말고 겔바스 그림게이트에게 가서 교환하세요! 다섯 개 이상만 있으면 누구나 이 세상에서 최고로 멋진 상품을 받을 수 있으니까요. 꽝은 없으니 안심하셔도 좋습니다!"
rows["404:1634648774"]="우리는 그녀를 지휘관에게 데려갔는데, 원의 드루이드가 그녀를 고칠 수 있었으면 좋겠다고 생각했고, 우리는 원과 우리의 일이 끝났고, 다시 일할 수 있다고 생각했습니다.$B$B몇 주가 지나고 모든 것이 잘 진행됐습니다. 브랜은 그 당시에도 여전히 주변에 있었고, 그래서 우리 작업 구조는 조금 정리되었어요. 어느 날 갑자기 그녀는 우리 캠프에 돌아왔습니다.\010"
rows["404:24084381"]="많은 사람들이 이런 술집이나 축제에서 낭만적 인 관계를 추구한다는 것을 이해하지만 알코올은 감각을 둔화시키고 일상 생활의 어려움을 계산하는 것을 미묘하게 만듭니다!$b$b하지만 저는 해결책을 찾았습니다. 많은 시행착오를 겪으면서, 놀라운 기기를 만들었습니다. 이 안경을 착용하면 누구나 매력적으로 보일 수 있습니다!$b$b너 포함해 귀여운 내가 할인해"
rows["405:1313212806"]="만약 당신이  ⁇ 가르마르쉬에 있다면, 다니엘스라는 사람을 만나게 될 수도 있습니다.$B$B물론 내가 그에게 그가 아는 모든 것을 가르쳐줬어$B$B좋은 옷이 속이지 마, 내 마음은 여전히 악당이야, 다니엘스와 나는 격포에서 함께 많은 시간을 보냈지만, 그건 내가 은퇴하기 전에였어."
rows["405:1473242341"]="어쨌든 우리는 기계에 많은 모래와 기름을 펌프해야 했습니다. 근처의 수영장은 그 일을 할 수 있는 완벽한 장소였습니다.$B$B모래의 일부에는 마법의 성질이 있다고도 증명됐는데... 가능성은 뭐라 할 수 있겠지?$B$B그래서 우리는 대부분의 물을 배수하고 중앙에 펌프 스테이션을 세웠고 어느 날 주입 파이프가 막혀지기 전까지 모든 것이 잘 진행되었습니다."
rows["405:192611501"]="다크월 페어에 오신 것을 환영합니다. 세계 최고의 이벤트입니다! 우리는 모든 것을 가지고 있습니다... 맛있는 음식, 강 음료, 이국적 유물, 운명 읽은, 놀라운 상과 끝없는 흥분을! Gelvas Grimegate에 당신의 다크월 페어의 상 티켓을 돌려 잊지 마십시오! 5 개 이상의 걸립니다. 그리고 당신은 모든 아웃랜드에서 가장 멋진 상으로 가는 길에 있습니다. 모두가 승자가!"
rows["406:1624515993"]="그레타가 제이덴어와 그녀가 생각하는 사람들이 페일우드에서 부패에 책임이 있다고 생각하면서$B$B땅 의 생명 들 에게 어떻게 영향 을 끼쳤으며, 그 들 의 고통 을 끝낼 수 있도록 해야 할 일은 무엇 입니까?$B$B불행히도 부패는 너무 깊어서 영원한 수면이 너무 자주 해결책입니다."
rows["406:1696205670"]="하하! 그들의 지도자를 제외하고 - 사타이르, 바잘란, 마녀 제고시 - 네, 그들 모두. 그래서 나는 끊임없이 Thrall의 숭배자를 그들에게 보내. 그것은 그의 위대한 도시의 내장에서 악을 제거하고 있다는 인상을 Thrall를 제공합니다. 승리는 실제로 두 가지: Thrall의 신자들을 죽이고 그들이 정말로 나에게 합류할 가치가 있는지 확인하기 위해 세어링 블레이드에있는 사람들의 힘을 테스트."
rows["406:2016769984"]="제이드 뱀의 성전, 제이드 숲에 있는 수준 85-87 던전, 이제 테스트를 할 수 있습니다. 던전으로 이동하기 전에 전체 그룹에 가입하시기 바랍니다. 멘팅 스톤은 아직 이 던전에서 사용할 수 없습니다.\010사자 용의 성전에서 나가려면 그냥 정규 출구로 감옥 안으로 들어가서 탈송될 겁니다."
rows["406:384942714"]="이 예의를 베풀어 $p오늘 여기서 일어난 일을 가르로시에게 공유하지 마세요. 저는 직접적으로 그와 대면할 수 있지만, 이제 모든 오크들이 호드.$b$b내가 다른 독재자가 되어서도 그들의 충성을 명령할 수 있는 나 누구인가?$b$b내가 할 수 있는 건 다크스피어들이 전쟁에 해외에 있을 때 그들의 집을 강화하는 데 도움이 되는 거야 볼진이 돌아왔을 때 다음 움직임을 계획할거야"
rows["406:74682242"]="모고'샤인 궁전 (Mugu'Shan Palace) 은 영원한 꽃의 계곡에 있는 수준 87-89의 동굴이다. 동굴로 이동하기 전에 전체 그룹에 가입해 주시기 바랍니다. 이 동굴에는 아직 미팅 스톤이 없습니다.\010모구'샤프 궁전을 떠날 때, 그냥 정규 출구를 통해 빠져나와 감옥 안으로 들어가면 다라란으로 이동할 것입니다."
rows["407:1202766728"]="달이 가득한 동안, 제이드 숲에서 잃어버린 숲의 스프라이트 다터들은 그들의 척수를 떨어뜨리는 것으로 알려져 있습니다. 그들은 밤에 늦게 그렇게합니다. 실제로는 보기 아름답습니다. $b $b 그들의 척추는 밝은 자이드 빛으로 빛나고 물 속으로 튀어나오게 됩니다. 이것은 당신이 믿지 않을 것처럼 자이드  ⁇ 어 물고기를 끌어들이죠! 빛! $b $b 하지만 그 모그들을 방해하지 않도록 조심해"
rows["407:2120456594"]="로어워커들은 문화 유물을 찾기 위해 판다리아의 중요한 지역을 탐험하도록 보내줄 것입니다.$B$B컬렉션에 속하는 모든 유물을 발견하면 처음부터 끝까지 이야기를 들을 수 있습니다.$B$B모든 유물을 찾아서 책들을 모아 로레워커가 되라!$B$B연구자가 되고 싶다면 지식의 자리에 있는 로리워커 쇼와 이야기해봐"
rows["408:1206471377"]="보석 제작은 마법의 반지, 무술, 보석, 그리고 베어진 보석을 만드는 데 도움이 됩니다.\010보석공업에 사용되는 보석들은 광업에서 수집된 광석에서 채굴을 통해 구입하거나 획득될 수 있습니다. 이 때문에 두 직업은 잘 결합됩니다.\010대부분의 주얼크래프트 디자인에는 주얼러 키트가 필요하지만 더 고급 크리에이션에는 단순 밀러가 필요하며, 이러한 것들은 주얼크래프트 공급업체에서 구입할 수 있습니다."
rows["408:1212389824"]=" ⁇ 드라라라족은 아즈하라 여왕의 가장 존경받는 고고학자였습니다. 바로 이 벽 안에서 여왕의 가장 중요한 요구가 처리되었는데, 종종 비밀리에 이루어졌습니다.$B$B우물 파괴와 그 후의 침착으로, 하이번과 작은 밤 elf 세파를 극복한 후, 엘드레'타라스 왕자 토르텔드린은 서쪽 날개의 홀에서 쓰레기를 찌르는 것을 볼 수 있는 기둥의 건설을 시작했습니다.\010"
rows["408:1385825785"]="유령들의 힘은 악마 사냥꾼으로서 매우 높다는 것은 놀라운 일이 아닙니다. 결국, 시나'도레이는 야간 유령들이 하는 것처럼 귀신 마술에 대한 자연적인 혐오가 없습니다.$B$B하지만 많은 사람들이 성공할 것이라고 기대하지 않습니다. 바디스도 포함해 그들 대부분은 권력을 추구합니다. 그 힘은 그들을 소모합니다. 왜냐하면 그들은 진정한 악마 사냥꾼의 마음 속에 불타는 순수한 불에 의해 움직이지 않기 때문입니다."
rows["408:574371880"]="'한은 목을 닦아주네.'$B$B우리는 시어링 골리 터널을 거쳐 골리를 이루는 황폐화된 황폐지대에 들어갔습니다. 과거로 돌아보면, 모든 것이 끔찍하게 조용했습니다. 우리가 마주치는 유일한 위험은 지역의 야생동물이었습니다.$B$B우리는 비교적 쉽게 블랙록 산에 도착했고, 돌로 만든 공사를 통과해 지침없이 길을 걷게 되었습니다."
rows["409:1870260059"]=" ⁇ 머런 페어 시상식 티켓은 멋진 상을 구매할 수 있는 통화입니다$b$b상권은 월간 임무를 수행하고 페어 주변 게임을 하는 것에 대해 보상됩니다.$b$b월간 임무를 완료하면 가장 많은 상권을 얻을 수 있지만 매일 게임을 하는 것은 앞으로 나아갈 좋은 방법입니다.$b$b일단 티켓이 충분하면 파어 지대의 다른 판매자에게 쓸 수 있습니다."
rows["409:54435775"]="그 모든 것은 어떤 파트너를 의미하느냐에 달려 있습니다. 수년 동안 많은 사람들이 왔고 갔습니다. 항상 전설의 버드 네드렉의 코트-테일을 타고 싶어하는 사람!$b$b여러분들은 그들 중 대다수가 부유하고 은퇴한 것을 확신할 수 있습니다. 제가 선택한 길은 아닙니다. 저는 항상 세상의 위대한 비밀을 밝히기 위해 부름을 받았다고 느꼈습니다. 아쉽게도, 제가 그렇게 하지 않는다면 누가 할 수 있을까요?\010"
rows["409:567636973"]="네파리안은 부적절한 주체들이 즉시 파괴되도록 명령했지만, 이  ⁇ 은 짐승들은 먼저 '큰' 정도의 고문을 당하지 않으면 그렇게 하지 않을 것입니다.$B$B우리 는 철저 히 '부러'었을 때, 그 들 은 남은 것 을 모아 그 들 의 악당 들 에게 던져버리곤 했습니다. 우리 의 몸은 그 들 의 병든 놀이에 도구 로 사용 되었읍니다."
