rows["40:933303106"]="오늘 물이 어떻게 흐르고 있어 여행자?"
rows["40:934262707"]="난 널 고통의 도시로 데려갈거야"
rows["40:934567806"]="- 당신이 보는 것을 좋아해?"
rows["40:936618400"]="물론!$B$B문제는 뭐죠?"
rows["40:936637681"]="잠깐, 고블스!"
