rows["40:944069180"]="%s 그녀는 멈춘 동안 심하게 숨쉬고 있습니다."
rows["40:946250241"]="아마 지금부터 내가 '$p-피트'라고 부를지도 몰라"
rows["40:946293018"]="%s 마우리의 구슬발을 열려고..."
rows["40:947846440"]="자유클이 들어오지 못하게 해!"
rows["40:949038007"]="내 문제가 아니야, 메스너"
rows["40:966706315"]="마법사와 다시 싸울 준비가 됐어"
rows["40:967818601"]="우리의 존경받는 워치퍼가 어떻게 당신을 실망시켰습니까?"
rows["40:968926712"]="좋아, 놀이 끝났어, 죽여야 돼"
rows["40:970168877"]="왜 이런 큰 당근이 필요할까요?"
rows["40:973446346"]="난... 난 오빠가 죽은 줄만 알았어."
rows["40:984481251"]="더 많은 증인들이 없을까요?"
rows["40:988570341"]="공격하는 불 원자들을 물리치 %s!"
rows["40:992032814"]="이제 우리가 안전하다고요? 그게 정말입니까?! 야호!"
rows["40:993017963"]="어떤 도움이 될 수 있을까요? 호드어쨌든?"
rows["40:993537454"]="그는 지쳐서 바닥에 쓰러진다."
rows["40:993848176"]="난 널 이렇게 혼란스럽게 여기 두고 싶지 않아"
rows["40:994648802"]="%s은 당신에게 공허한 손을 들고 드리고 있습니다."
rows["40:995589231"]="내가 화학자로 훈련하고 싶어, 다델"
rows["40:99705494"]="손잡이 바늘처럼 낫지 않는 건 없어요"
rows["40:997878610"]="이 방패가 너무 강해"
rows["40:998480975"]="그렇지 않으면, 난 정말로 길을 잃어 버렸어."
rows["40:999319786"]="피 냄새가 나고, 벼룩이 싸우기 싫어요"
rows["410:1027177773"]="십자군...$B$B<리벤데어'가 머리를 흔들고 있다.>$B$B저는 이 동물들이 인간들 가운데 독특하다고 확신합니다. 제 이론은 그들이 더 높은 뇌 기능을 가지고 있지 않으며, 상황을 논리적으로 평가하고 결과를 계산할 수 없다는 것입니다. 한 사람은 단지 빛를 언급해야 합니다."
rows["410:1176087002"]="차인은 타이틀을 쉽게 획득하지 못했고 마을의 네 구석에서 모여있는  ⁇  제조업자들의 치열한 챔피언십이 있었습니다.$b$b이곳은 바닐라 끓는 물 때문에 엄청난 치열함으로 싸웠고 하루 여행에 만들어진 최고의 누드러를 만들어내기 위해서였죠.$b$b영광스러운 것 같군$b$b오직 퓨어푸리만이 승리하게 되었는데, 스파커의 그릇을 흔들릴 정도로 놀라운 누드를 만들었죠."
rows["410:1693013739"]="아르헨티나 십자군 전쟁은 과거의 일이라고 말하는 사람들이 있습니다. 저는 그들 중 한 명이지만, 스컬지가 무너졌기 때문이 아닙니다.$b$b아니... 그들의 거친 방식 때문에요. 그들은 너무 분리된 교회와 비슷해졌습니다. 너무 딱딱하고 명예와 질서로 지배되고 있습니다.$b$b물론 좀 무관심한 소리지만 좋은 논쟁을 불러일으키죠"
rows["410:177785867"]="<고르무난은 의심의 여지를 가지고 백신을 보고 후취를 하고, 눈에 보이는 자극으로 백신을 찌르고 갓마귀 모양으로 만들어 냅니다.>$B$B당신의 작은 친환경 친구들이 당신을 나쁜 짓으로 만들거라고 의심합니다.$B$B<그목을 증명하기 위해 고르무난은 초콜릿 괴물 동상을 돌려주기 전에 머리를 꺾는다.>"
rows["410:1899728225"]="제가 확실히 모르겠지만, 몇 천년 안에, 우리가 필요한 아이스크림과 함께, 충분히 익살을 할 수 있을 것 같지만, 우리는 충분히 있을 것 같습니다. 아니면 어쨌든, 제가 들은 바와 같습니다. 여기 있는 다른 사람들이 수집하는 어떤 것에도 도움이 필요할 것 같습니다."
rows["410:192314970"]="저는 라그나로스의 부패가 어둠의 철나라의 마음과 마음속에 퍼져나가는 것을 지켜봤습니다.$B$B스파이어의 건설이 완료되면, 내 백성들 사이에서 살겠다는 의지가 사라졌습니다. 저는 새로운 다크 아이언 국가의 영웅으로 거쳐갔습니다. 이 무덤은 제 계획과 건설한 도시의 입구에 세워졌습니다."
rows["410:1988053290"]="이 태양이 불어넣은 도시는 특히 무자비한 무자비함과 어두운 신비로움을 가진 샌드푸리 트롤들의 고향이다. 트롤 전설은 툴'트레이즈 라셔라는 강력한 검에 대해 이야기합니다. 가장 무서운 적들에도 두려움과 약점을 심어줄 수있는 무기입니다. 오래 전에, 무기가 반으로 갈라졌습니다. 그러나 두 반은 툴'파락의 벽 안에 어딘가에 발견 될 수 있다는 소문이 퍼져 있습니다.\010"
rows["410:347254940"]="창조자들은 외부와 내부의 힘들이 그 힘과 관련된 매트릭스 역학을 방해할 때, 방문을 씨앗화된 세계들에 대한 통제를 회복하는 수단으로 사용한다. 그러한 전술은 창조자들이 실행할 때 가볍게 받아들여서는 안 된다.$B$B이 세상 에 계획 된 방문 에 대한 추가 정보 를 위해, 창조주 와 관련 된 모든 계획 의 고려 사항 을 포함 하는 적절한 데이터 저장소 를 참조 하십시오."
rows["410:670673009"]="에스메랄드 드래크는 자신의 적들을 독해주는 동시에 스스로를 치유하는 데 탁월하다.\010이 독을 반복해서 사용하면 그 효능이 증가할 수 있습니다.\010악몽을 만지면 에스메랄드 드래크는 꿈에 도달하여 그들의 생명 에너지를 매우 유해한 공격으로 변환시켜 목표물을 약화시키고 짧은 시간 동안 그 피해를 줄일 수 있습니다."
rows["410:68142718"]="여러분, 이 끔찍한 시기에 포세이큰에 도움이 되는 것이 여러분의 이익입니다.$B$B현재 우리는 천재가 극히 부족하고 있습니다. 붕대와 단순한 섬유는 부족하고, 재고가 쇠퇴하는 것을 강화하기 위해 기부금도 받아들여지고 있습니다. 당신은 재정적 보상을 받지 못할 것이지만, 기부금이란 무엇인가요."
rows["410:689746707"]="훔친 물품?$b$b다리아라는 신부 한 명도 알고 있는데 지난주 예배를 마치고 잔잔한 와인도 다 먹었지만 내가 요청한 대로 내버려두지 않았는데$b$b<알푸스는 눈 ⁇ 을  ⁇ 다.>$b$b이번 주 마법사 한 명으로부터 비정상적인 고백도 들었습니다.$b$b이제, 가자"
rows["410:798328635"]="지난 몇 년 동안 furbolg에 끔찍한 일이 일어 났을 것을 보았습니다. 그들은 여러 전면에서 희생되었습니다. 하지만 이 부족이 어떻게 되었는지 나에게는 분명하지 않습니다. 그들은 Felwood에 영향을 준 같은 전염병으로 손상되었습니까? 또는 아마도 그들은 단지 평화로운 사람들이 일어난 일에 분노하고 스스로를 방어하려고합니다. 어떤 방식으로든, 그들 대부분은 지역에 들어온 사람들에게 적대적이라고 보입니다."
rows["411:1426480985"]="저는 트랄의 아타스에게 분노를 느낄 수 있지만, 그것은 내 자신의 것보다 더  ⁇ 니다. 그가 포세이큰 중 어느 누구처럼 분노한다면 호드의 군대는 노스렌드에 분노를 일으키고 저 저주받은 얼어붙은 황폐지에서 모든 스컬지을 근절시킬 것입니다.$B$B하지만 저는 이 호드트롤은 이 시기가 행동의 시간임에도 불구하고 그의 선택권을 고려하고 싶어 하지만 우리의 시간은 곧 올 것입니다"
rows["411:1778416619"]="저주를 위한 암호는 20년 동안 카라보르에 있는 구르단의 사방에서 보관됐어요$B$B블랙 테플...$B$B예, 이제 일리던 스톰라이지의 집으로$B$B이리던이 블랙 테플을 장악했을 때 그는 암호를 발견했고 이 세상에 이미 피해가 발생했음을 인식했지만 나중에 사용할 수 있도록 암호를 안전하게 보관하는 것이 현명하다고 생각했습니다."
rows["411:2133990286"]="수 년 동안 이 숲은 불타오르고 있습니다. 고대 마술에 의해 조화되어 있으며, 새끼 어머니와 그녀의 원동물 배우자의 짝짓기 지대가 됩니다.$B$B하지만 이제 오래 잊혀진 악이 다시 일어나서 자생 어머니의 자손을 다시 노예로 삼으려 합니다.$B$B이 자유클은  ⁇ 의 경계를 확장하고, 당신의 사람들을 위협하는 혼란을 일으켰습니다."
rows["411:441994733"]="수도원은 한때 교육과 깨달음의 중심지였는데 스컬지 제3차 전쟁 때 평화로운 수도원은 붉은십자군십자군들은 인간과 다른 모든 인종에 대해 얼라이언스 그들은 외부인이라면 누구나 유동병의 잠재적인 운반자라고 믿고 파괴되어야 한다고 믿습니다. \010"
rows["411:676493679"]="그 거창들은 우리를 보고 너무 행복하지 않은 다양한 시리티드들로 가득했습니다.$B$B모든 게 잘 진행 중이었는데, 하비레갈에서 글리프 된 크리스탈을 발견할 때까지요. 그녀는 불꽃에 대한 벼룩처럼 그 쪽으로 끌려갔어요! 그녀는 그녀의 아름다운 작은 양쪽  ⁇ 을 크리스탈에 올려놓고 즉시 트랜스 같은 상태로 들어갔습니다. 당연히, 이것은 제 팀원들을 걱정시켰습니다. 우리는 그녀를 데려다가 빨리 밖으로 가져갔습니다."
rows["412:1033889694"]="그래서 노인  ⁇ 은 동굴에 갇혀있어서, 그는 그의 신실한 무산에게 휘파람을 피하는 것 외에는 뭘 하겠나?$B$B그리고 곧, 그는 붐의 소리를 듣고, Bobo는 바로 그 동굴에 구멍을 뚫고!$B$B그 무산은 그의 주인에게 귀를 기울이고 그를 찾아오게 해!$B$B그리고 그 다음, 무슨 일이 일어나지만 전체 동굴이 흔들리고 천장이 무너지기 시작합니다.$B$B그래서 노인  ⁇ 이 보보의 등에 뛰어들어, 그 다음에 무슨 일이 있었는지 아세요?"
rows["412:2130309526"]="이 포스트를 지키고 탈출을 막으라고 명령했지$b$b괜찮아, 통과할 수 있지만 먼저 부탁을 드리겠습니다$b$b트롤들은 종종 랩토르 음식들을 가지고 있고, 며칠 동안 먹이지는 못해 전투에서 기회를 잡지 못하지만,"
rows["412:217781661"]="제 형제 들 의 대부분 은 호드 의 \"바르바르적\" 인 방법 을 경멸 합니다. 그리고 한 때 저는 그 들 가운데 나 를 포함 해 보았습니다.$b$b하지만, 학창 때 에 우리 의 주변 에 있는 것 들 을 중요 히 인식 하게 되었는데, 그 들 의 매력 은 어느 정도 가 있다고 생각 하지 않나요?$b$b물론 제 연구들은 다른 마법사들이 마법으로 돌아올 수 있게 해줬습니다."
rows["412:506952768"]="어제 밤 스노우드리프트 마스터는  ⁇ 라이 정상에 있는 샤도파네 수도원에서 수업을 하고 있었습니다. $b $b 좋은 소식은 학생들이 훌륭하게 공부를 했습니다. 나쁜 소식은 수백 개의 얼음 펀드 공이 물에 던져졌다는 것입니다.$b $b 오늘 호랑이 가우라미를 잡으려 한다면, 아마 그게 가장 좋은 방법일 겁니다."
rows["412:953437551"]="아르헨티나 새벽은 무력한 이상주의자일 수도 있지만 그들의 환상적인 지도자는 그들이 능가한다는 것을 알고 있습니다. 나는 여기에 붉은십자군의 비로소 보내졌습니다. 대사, 당신이 원한다면... 우리는 심지어 켈'투자드의 군대를  ⁇  수 있을 것조차 의심스럽습니다. 연합하거나 그렇지 않더라도 - 그러나 우리는 어떤 기적이 일어나기 위해 충분히 그들을 억제 할 수 있을지도 모릅니다.$B$B내겐 전쟁에서 죽을 거야$B$B<마르얀은 껴안는다>\010"
rows["413:1126841071"]="먼저 게임 토큰 하나 줘서 스팀톤을 조종하게 되죠$b$b전투장에서 목표물을 폭발시킬 시간이 제한되어 있습니다. 파괴하는 목표마다 1점으로 얻을 수 있습니다.$b$b하지만 조심하세요. 전투장에는 적의 탄기와 제펠린도 있습니다.$b$b당신의 점수는 한 톤에서 다른 톤으로 전달될 것입니다. 그래서 당신이 폭발하면 걱정하지 마십시오."
rows["413:1766876215"]="<제이나는 심심한 생각을 하고 머리카락을 닦아준다.>$b$b당신은 당신의 일에 열정적이고, 당신의 신념은 명확합니다. 호드 그들의 가족입니다.$b$b다 가로쉬를 지지하지는 않지만, 그들은 자기 백성을 포기하지 않을 겁니다.$b$b키린 토르는 내게 신성한 곳이야"
rows["413:837834977"]="전쟁 때, 오크들이 용을 타고 갔을 때, 휘슬러와 나는 체리 그로그에 눈알까지  ⁇ 을  ⁇ 고 있는 동안$B$B'우리는 제 계산에 의해 약 1/3의 길을, 대부분 멀리 판단' 우리가 바다에 의해 주위에 아무것도 없다는 사실에 의해, 내 발에 젖은 느낌 시작했을 때."
rows["413:891091258"]="네더윙. 그들은 우리에게 이야기 합니다. 그들은 우리에게 평화와 보호를 제공했습니다. 부진한 사람들은 결코 진정으로 느끼지 못했던 것. 우리는 그들의 제안을 받아들였고, 토라나쿠에게 이 광산의 생물들을 깨우는데 큰 개인적인 비용을 지불했습니다. 많은 형제들은 이 공격에 목숨을 바쳤습니다. 우리는 광산을 살 수 없게 만들려고 노력했습니다."
rows["413:91721159"]="고고르드는 십자군 전쟁 의 린치 피드 이었다. 예, 모그라인 은 리치 왕 의 군대 와 대 한 그의 전력 때문 에 애쉬브링거 라고 불리 었습니다. 칼 과 믿음 을 가지고만 있으면서 모그라인 은 무사 의 전단 들 을 걸고 무해 로 나오게 되었으며 - 그의 적 들 의  ⁇ 은 그 들 의 존재 를 단 한 가지 증거 로 그 들 의 존재 를 알 수 있었다."
rows["414:2038255594"]="레이 라인 발굴 작업은 계속되고 있으며, 좋은 결과로 이어지고 있습니다. 우리는 아제로스와 드레노르 사이의 레이 라인 구조에서 비슷한 몇 가지 유사점을 발견하여 놀라게 되었으며, 아마도 유사한 발생을 나타냅니다?\010내 가까운 동료 나베리우스 는 웃는 두개골 들 이 그 지역 에 있는 얼라이언스군 과 휴전 협정을 맺었다고 보고 한다. 오크 들 을 항상 불신 하게 되어, \"이것이 천국 이거나 지옥 이 될 수 있다\"고 생각 했습니다.\010"
rows["414:686794278"]="그래서  ⁇ 은 스파ンの 래바 구덩이에 앉아, 내 래바 드레스를 테스트하고 있었는데, 모든 것이 훌륭했습니다.$B$B그래서 저 여기 있어요. 제 일을 하고, 몇 번의 척추를 하고, 갑자기 이 물건이 날 완전히 삼키고 있습니다."
rows["414:782498414"]="타이탄들은 하루아침에 생명을 창조하지 않았습니다. 이 과정은 점진적이고 많은 실험과 반복이 필요했습니다.$B$B바로 그 이유 때문일 때, 쇼라자르盆地와 같은 보호 구역이 존재합니다.$B$B실험장치를 안전하게 하기 위해 타이탄들은 방어 장치를 만들었습니다. 하지만 파괴력은 무궁무진하고,"
rows["414:930462786"]=" ⁇ 로망스가 세워진 땅은 바로프 가문이 켈'투자드에게 주었다. 이 땅 대가로 - 저주받은 사람들의 숭배가 스컬지의 불쾌한 마술을 배울 수 있는 장소 - 켈'투자드는 죽은자를 통해 바로프의 불멸을 부여했다.$B$B그림자보존에서 그림자의 피부와 그 소유자인 이루시아 바로프 여인을 찾을 수 있습니다.$B$B헛된 사람들, 죽은 사람들, 더 나은 거울은 존재하지 않았습니다."
rows["415:1051116765"]="호드는 아웃랜드에 많은 위험을 감수했습니다. 자원, 인력 - 심지어 우리 땅의 전술적 방어도 위기에 처해 있습니다. 다른 모든 것에 불구하고, 트랄은 이 황폐화된 땅의 약속을 믿습니다. 요즘 그의 눈에 이상한 빛이 있습니다. 마치 그는 우리 나머지 사람들이 느끼지 못하는 어떤 자극적인 계시를 감지하는 것처럼.$B$B하지만 그는 내 장갑이자 내 혈연형자였어"
rows["415:1684740444"]="무슨 일이 없지?$B$B세계 각지의 숙소 주인은 모두 트릭 오브 트레이트 선품 을 배포 하고 있으며, 많은 도시 들 은 시즌 에 맞게 장식 되어 있다! 또한, 사우스셔 에 있는 하트먼 장교 는 포세이큰 와 그 들 의 위커먼 축제 에 대항 해 도움 을 필요로 한다.$B$B또 한 가지 더 들어봤습니다. 스톰윈드년 고아원에서 병든 소년이 휴가 기념식에서 감자품을 모으는 데 도움을 주고 싶어한다는 것을요."
rows["415:1837613260"]="이런포에에, 전설적인 오크가 죽이는 해마어? 그래, 그래, 그건 윈저의 해마어였어. 그는 그 해마어를 프랭클론 포워라이트가 자신의 큰, 큰, 큰 할아버지에게 직접 만들었다고 말했다."
rows["415:2001438576"]="'탈론 킹' 이키스는 제 형제인 다크웨이버 사이트와 함께 세테크의 지도자 중 한 명입니다.$B$B스케티스에서 오치윈의 유적지로 세테크크의 탈출을 이끌었던 이들은 처음엔 이키스는 카리스마적인 지도자였지만 그는 미쳤어요.$B$B이제 그는 자신이 테로크라고 공개적으로 선언합니다 되살아난 자아라코아족이 그를 통치자로 무릎을 꿇길 바라고"
rows["415:2003910183"]="여기로 가는 길에 경관을 똥으로 닦은 뼈골자 창조물들을 놓쳤어?$B$B로한은 숨쉬고 있다$B$B야외의 종류라면 서부와 동부 플레그랜드에서 골격적인 생물들을 발견할 수 있습니다. 믿으세요, 그들을 놓칠 수 없습니다. 그들은 기회를 얻으면 당신을 놓치지 않을 것입니다.$B$B만약 당신이 감옥의 유형이라면 스트라톨메와 쇼로망스는 뼈 조각을 위한 장소입니다."
rows["416:1138847290"]="몸의 힘은 행동의 힘과 신속성입니다. 당신은 항상 신체적, 정신적 양쪽에도 몸을 건강하게 유지해야 합니다. 곰의 둘레는 전투에서 야만적인 적이기 때문에 그 강점을 강조합니다. 하지만 곰의 둘레가 그 빛에 반해 있습니다. 민첩성 그리고 똑똑한 마음을 가지고 있어$B$B곰의 몸의 힘에 의존해야 손톱의 길을 능숙하게 할 수 있습니다."
rows["416:1330656258"]="이 화산적 험담은 한때 암흑 철의 거처였던 라그나로스 불의 주인에게 힘의 거처로 작용했다. 라그나로스는 돌로부터 생명을 창조하는 비밀을 밝혀내며, 블랙록 산 전체를 정복하는데 도움을 줄 수 있는 막히지 않는 고렘 군대를 건설할 계획이다. 네파리안과 그의 드라코닉 하위들을 물리치려는 집착으로, 라그나로스는 최종 승리를 얻기 위해 모든 극단으로 갈 것이다.  \010"
rows["416:1410335053"]="순진한 바보. 불타는 칼은 그림자 협의회입니다. 협의회 통치 아래 많은 교파와 조직이 있지만, 모두 그들의 의지의 확장입니다. 나는 불타는 칼을 이끌 수 있지만, 나는 여전히 협의회에 대한 보인물이 당신처럼 나에게 있습니다!$B$B ⁇ 어있는 칼을 보세요. 그들 대부분은 그들이 그림자 협의회를 대체할 강력한 마법사의 다음 그룹이 될 것이라고 생각합니다."
rows["416:2095330318"]="한마디로 마법이라고$b$b책임 없는 필사자들은 그들의 짧은 생애에 대해 그들의 행동의 지속적인 영향에 대해 전혀 생각하지 않습니다.$b$b미묘한 에너지들은 너무 자유롭고, 세계의 균형을 방해해 왔습니다. 만약 이런 일이 계속될 수 있다면, 아제로스은 곧 멸망할 것입니다.$b$b이 부분에 대해서는 양측 모두 동의하지만, 협의회가 임명되기 전에 마일고스는 자신의 계획을 실행했습니다.$b$b우리는 그를 대면하는 것 외에는 선택의 여지가 없었습니다."
rows["416:917939385"]="이 편안한 동굴에서 그 생물들이 우아하게 공중에 선을 잘라내는 것을 감탄하고 지켜보세요.$b$b존재는 당신의 존재를 인식하지 못하지만, 당신의 모든 숨결을 알고 있다는 느낌을 내립니다.$b$b나즈그림과 그 다른 사람들을 생각하면 낯선 사람을 대화에 참여시키는 가장 좋은 방법을 고려합니다.>"
rows["417:399130971"]="우리가 부르려 왔어$b$b우리는 초기에 '하이프 차이ftan Baine Bloodhoof'의 명령에 따라 미지의 물 속으로 파묻혔습니다.$b$b제 아내 레즈라는 그 비전을 통해 우리가 갈 수 있는 길을 제시했습니다.$b$B하지만 안개가 있는 벽을 보고 우리는 모두 바람의 목소리처럼 불기 시작했어요. 북쪽에서$b$b우리는 해안으로 왔고, 우리 배를 철거하고, 앞의 절벽에 도달하기 전까지 캔로로 강을 타고 항해했습니다."
rows["418:1065857140"]="Felwood에 있는 식물들이 있습니다. Cenarion 식물 살림을 적용하면 부패로부터 구해질 수 있습니다. 여러 종류의 물체에서 살림을 만드는 방법을 알고 있습니다.$B$B또한 이 작업에 필요한 센리온 광선이 있습니다. 그것은 맨눈으로 볼 수 없는 자연의 훼손과 부패를 볼 수 있는 장치입니다."
rows["418:1679173992"]="사우르 사제들은 우리의 힘이 크로시크로부터 왔다고 말할 겁니다. 그들의 종교적인 말을 듣지 마세요.$b$b우리의 힘은 손톱, 치아, 무기로부터 나온다.$b$b우리한테서 온 거야$b$b우리가 하늘에서 있는 악마의 산소에서 온건 아니면 모가들이 만든건 상관없어요"
rows["418:2020154244"]="아웃랜드 최고의 쇼에 다시 오신 것을 환영합니다, 내 친구!$B$B여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분, 여러분들이 모두들께 이 모든 나이들께 이"
rows["418:442833701"]="이봐, 내가 본 건...$b$b나무를 지나가는 바람처럼 울리는 소리를 들릴 때까지는 조용한 곳이었죠. 우리가 알아차리기 전에, 우리는 이 아만리와 애완동물들에 둘러싸여있었죠.$b$b하루가 지날수록, 잡힌 스카우트들이 죽어가고 있습니다.$b$b그 케이지에서 배운 게 전부 다"
rows["418:467754902"]="그 더러운 짐승들은 곳곳에 있습니다.$B$B야외에서 사냥을 선호한다면, 대부분의 동물은 플라그우드와 테러데일 주변에서 발견되며, 테러 웹 터널에 잘 집중되어 있습니다. 스컬지 동부 플라그랜드에 진영하고 있습니다.$B$B만약 당신이 거창의 거창을 탐색하는 사람이라면 스트라톨메에서 그 종류를 많이 발견할 것이고, 슐로마네스에서는 네크로피엔드 종류를 발견할 수 있을 것이다."
