rows["419:819402220"]="그래서 오늘 제가 물품을 수집하던 중, 저는 외래적인 술과 기름을 판매하는 방황하는 셰르파를 발견했습니다.  $b $b 그가 어떻게 만든지 상관없어, 이 물건이 정말 효과가 있다는 걸 알아! $b $b 니우자오 성전 북쪽의 호수에서 찾았어"
