rows["41:1014612379"]="얼라이언스은 드레네이 유적들을 점령했습니다!"
rows["41:1015111095"]="이곳에서 네가 맞이할 건 죽음뿐이다!"
rows["41:1024524301"]="난 전투에 참여하고 싶어요!"
